const C=(title,hi,what,why,how,example,mistake,check,whatHi,whyHi,howHi,exampleHi,mistakeHi,checkHi)=>({title,hi,what,why,how,example,mistake,check,whatHi,whyHi,howHi,exampleHi,mistakeHi,checkHi});
const QUIZ_WHY_HI = {"The interest base reduces as principal is repaid.": "मूलधन चुकाने के साथ ब्याज की गणना का आधार घटता जाता है।", "APR and disclosed costs reveal more than EMI alone.": "APR और बताए गए शुल्क केवल EMI से अधिक सही तुलना देते हैं।", "Do not share unnecessary personal data with unknown apps.": "अनजान ऐप के साथ अनावश्यक निजी जानकारी साझा न करें।", "It generally reduces interest cost when minimums are paid on all debts.": "सभी कर्ज पर न्यूनतम भुगतान करते हुए सबसे महँगा कर्ज पहले चुकाने से कुल ब्याज घट सकता है।", "A co-borrower can carry contractual liability.": "सह-उधारकर्ता पर अनुबंध के अनुसार कर्ज चुकाने की जिम्मेदारी हो सकती है।", "Insurance transfers specified risks under contract terms.": "बीमा अनुबंध की शर्तों के अनुसार कुछ तय जोखिमों का वित्तीय असर बाँटता है।", "The insured pays the stated share of eligible costs.": "पॉलिसी में तय पात्र खर्च का हिस्सा बीमित व्यक्ति खुद देता है।", "That is the basic design of a floater policy.": "फैमिली फ्लोटर का मूल नियम है कि बीमित राशि कवर सदस्यों में साझा होती है।", "The policy wording and schedule govern contractual cover.": "कवर, अपवाद और प्रतीक्षा अवधि पॉलिसी दस्तावेज़ और शेड्यूल में लिखे होते हैं।", "Keep records and use the insurer’s official grievance process.": "सभी रिकॉर्ड रखें और बीमा कंपनी की आधिकारिक शिकायत प्रक्रिया अपनाएँ।", "Mutual fund returns are market-linked and not assured.": "म्यूचुअल फंड का रिटर्न बाजार से जुड़ा होता है, इसकी गारंटी नहीं होती।", "Short horizons leave less time to recover from losses.": "कम समय होने पर नुकसान से उबरने के लिए कम समय मिलता है।", "Regular plans typically include distributor commission; compare scheme costs.": "रेगुलर प्लान में आम तौर पर वितरक कमीशन शामिल होता है; योजना की कुल लागत तुलना करें।", "Guaranteed high returns and urgency are common warning signs.": "बहुत ऊँचे गारंटीड रिटर्न और तुरंत निवेश का दबाव आम चेतावनी संकेत हैं।", "It returns holdings toward the target allocation.": "इससे निवेश का अनुपात तय किए गए लक्ष्य के करीब लौटता है।", "Cost and date make a goal actionable.": "लागत और तारीख लिखने से लक्ष्य पर काम शुरू किया जा सकता है।", "Actual costs may vary; make and revisit assumptions.": "वास्तविक लागत बदल सकती है; अनुमान बनाएँ और समय-समय पर दोबारा जाँचें।", "Include stamp duty, registration, repairs and financing costs.": "स्टाम्प ड्यूटी, रजिस्ट्रेशन, मरम्मत और कर्ज की लागत भी जोड़ें।", "Check eligibility, withdrawal and current rules on PFRDA sources.": "PFRDA के आधिकारिक स्रोत से पात्रता, निकासी और वर्तमान नियम जाँचें।", "Protect necessities and core obligations before flexible wants.": "पहले जरूरी जरूरतें और तय जिम्मेदारियाँ पूरी करें; लचीली चाहतों को बाद में रखें।", "It is issued by an employer for salary TDS details.": "नियोक्ता Form 16 में वेतन से काटे गए TDS का विवरण देता है।", "Reconcile official information with records before filing.": "ITR भरने से पहले आधिकारिक जानकारी को अपने दस्तावेज़ों से मिलाएँ।", "Understand the nature and context of the information.": "हर प्रविष्टि का प्रकार और संदर्भ समझें; हर जानकारी अपने-आप कर योग्य आय नहीं होती।", "Verify through the official portal and respond in time.": "आधिकारिक पोर्टल पर नोटिस जाँचें और दी गई समय-सीमा में जवाब दें।", "The Income-tax Act, 2025 commenced from 1 April 2026; transition provisions and year-specific rules matter.": "Income-tax Act, 2025 1 अप्रैल 2026 से लागू हुआ; संक्रमण व्यवस्था और संबंधित वर्ष के नियम भी महत्त्वपूर्ण हैं।", "Future needs may rise and healthcare can be a major cost.": "भविष्य की जरूरतें और स्वास्थ्य खर्च बढ़ सकते हैं; इन्हें योजना में शामिल करें।", "Nominee and beneficial/legal heir roles can differ by asset and law.": "नॉमिनी और अंतिम लाभकारी/कानूनी वारिस की भूमिका संपत्ति और लागू कानून के अनुसार अलग हो सकती है।", "Eligibility, lock-in and withdrawal rules differ.": "पात्रता, लॉक-इन और निकासी के नियम हर योजना में अलग होते हैं।", "Share where records are, not secret credentials.": "रिकॉर्ड कहाँ रखे हैं यह बताएँ, गुप्त लॉगिन या पासवर्ड नहीं।", "Complex structures have legal and tax consequences.": "जटिल ट्रस्ट और उत्तराधिकार व्यवस्थाओं के कानूनी तथा टैक्स प्रभाव होते हैं।"};
const Q=(q,opts,a,why,hi,optsHi,whyHi)=>({q,opts,a,why,hi,optsHi,whyHi:(typeof whyHi==='string'&&whyHi.trim())?whyHi:(QUIZ_WHY_HI[why]||why)});
